INSERT INTO bh_tracks (slug, title, summary, intro_md, bug_focus, assist_level, sort_order, status) VALUES ('spot-the-typo', 'Spot the Typo', 'Syntax errors: the code won''t even run yet.', 'Every puzzle here fails before it even starts. You''ll learn to read `SyntaxError` and `IndentationError` messages and fix the shape of the code, not its logic.', 'syntax', 'none', 1, 'published');
INSERT INTO bh_tracks (slug, title, summary, intro_md, bug_focus, assist_level, sort_order, status) VALUES ('crash-course', 'Crash Course', 'Runtime errors: the code runs, then crashes partway through.', 'These puzzles run until something goes wrong. You''ll learn to read a traceback from the bottom up and recognise what each exception type is telling you.', 'runtime', 'basic', 2, 'published');
INSERT INTO bh_tracks (slug, title, summary, intro_md, bug_focus, assist_level, sort_order, status) VALUES ('wrong-answer', 'Wrong Answer', 'The code runs fine and gives you a confidently wrong answer.', 'No errors here - just the wrong result. You''ll compare expected vs actual output and get used to checking boundary values by hand.', 'logic', 'full', 3, 'published');
INSERT INTO bh_tracks (slug, title, summary, intro_md, bug_focus, assist_level, sort_order, status) VALUES ('deep-bugs', 'Deep Bugs', 'Subtler logic bugs that need a trace table to really see.', 'These bugs hide in state, scope and recursion. You''ll use trace tables and variable watch to see what''s really happening, step by step.', 'logic', 'full', 4, 'published');
INSERT INTO bh_tracks (slug, title, summary, intro_md, bug_focus, assist_level, sort_order, status) VALUES ('boss-fights', 'Boss Fights', 'Bigger programs with more than one bug hiding in them.', 'Multiple bugs, longer code. You''ll divide and conquer, build minimal examples, and work the full debugging loop end to end.', 'mixed', 'full', 5, 'published');

-- Concepts
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('unclosed-brackets', 'Unclosed brackets', 'Every opening bracket needs a matching closing one.', '## What it is

Brackets - `(`, `[`, `{` - always come in matching pairs. Python keeps reading until it finds the close.

## What it looks like when it goes wrong

```
SyntaxError: ''('' was never closed
```

## How to spot it

Count opening and closing brackets on the line Python points to - they should match.

## How to fix it

Add the missing closing bracket in the right place.

## Try it

```python run
print("Hello")
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('strings-quotes', 'Strings and quotes', 'A string needs matching quote marks at both ends.', '## What it is

A string literal starts and ends with the same kind of quote mark, `"` or `''`.

## What it looks like when it goes wrong

```
SyntaxError: unterminated string literal
```

## How to spot it

Count quote marks in pairs, the same way you''d count brackets.

## How to fix it

Add the missing closing quote mark.

## Try it

```python run
greeting = "Hello, world!"
print(greeting)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('block-syntax', 'Colons and blocks', 'Every block header (if, for, while, def, class...) ends in a colon.', '## What it is

Any line that starts an indented block - `if`, `elif`, `else`, `for`, `while`, `def`, `class`, `try`, `except` - must end with a colon `:`.

## What it looks like when it goes wrong

```
SyntaxError: expected '':''
```

Python points at the end of the line that''s missing it.

## How to spot it

Scan every line that should open a block. Does it end in `:`?

## How to fix it

Add the colon at the end of the header line.

## Try it

```python run
for i in range(3):
    print(i)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('indentation', 'Indentation', 'Python uses indentation, not brackets, to show block structure.', '## What it is

After a colon-ended line, the body must be indented one level in, consistently.

## What it looks like when it goes wrong

```
IndentationError: expected an indented block
IndentationError: unexpected indent
TabError: inconsistent use of tabs and spaces in indentation
```

## How to spot it

Compare a line''s indentation to its neighbours - are they using the same character (spaces, not tabs) and the same amount?

## How to fix it

Re-indent consistently, using spaces throughout.

## Try it

```python run
def double(n):
    return n * 2

print(double(5))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('case-sensitivity', 'Case sensitivity', 'Print, print and PRINT are three different names to Python.', '## What it is

Python treats names with different capitalisation as completely different names.

## What it looks like when it goes wrong

```
NameError: name ''Print'' is not defined
```

## How to spot it

If a `NameError` names something that looks like a familiar built-in or keyword, check its capitalisation.

## How to fix it

Match the exact case Python expects - built-ins and keywords are lowercase.

## Try it

```python run
print("case matters")
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('assignment-vs-comparison', 'Assignment vs comparison', '= stores a value; == asks if two values are equal.', '## What it is

`=` assigns a value to a name. `==` compares two values and gives back `True` or `False`.

## What it looks like when it goes wrong

```
SyntaxError: invalid syntax. Maybe you meant ''=='' instead of ''=''?
```

## How to spot it

Look inside any `if` or `while` condition for a single `=`.

## How to fix it

Change it to `==` if you''re comparing, not assigning.

## Try it

```python run
x = 5
if x == 5:
    print("five")
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('keywords', 'Python''s keywords', 'Keywords are fixed, exact words - elif, not elseif.', '## What it is

Python has a fixed set of reserved words (`if`, `elif`, `else`, `for`, `in`, `and`, `or`, `not`, and more) that must be spelled exactly.

## What it looks like when it goes wrong

```
SyntaxError: invalid syntax
```

## How to spot it

If you''ve used another language before, double-check Python''s exact spelling rather than assuming it matches.

## How to fix it

Use Python''s real keyword (e.g. `elif`, not `elseif`).

## Try it

```python run
score = 72
if score >= 50:
    print("Pass")
elif score >= 0:
    print("Fail")
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('bracket-types', 'Bracket types', '(), [] and {} each mean something different.', '## What it is

`()` calls a function or groups an expression. `[]` indexes into a sequence or builds a list. `{}` builds a set or dictionary.

## What it looks like when it goes wrong

```
TypeError: ''builtin_function_or_method'' object is not subscriptable
```

## How to spot it

Ask: am I calling something, or indexing into something? That decides which bracket.

## How to fix it

Use `()` to call a function or method, `[]` to index.

## Try it

```python run
word = "hello"
print(word.upper())
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('function-syntax', 'Function definition syntax', 'def name(params): is the required shape.', '## What it is

A function definition always follows the shape `def name(parameters):`.

## What it looks like when it goes wrong

```
SyntaxError: invalid syntax
```

## How to spot it

Check every `def` line has all four pieces: `def`, a name, parentheses, and a colon.

## How to fix it

Add whichever piece is missing.

## Try it

```python run
def square(n):
    return n * n

print(square(4))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('names-and-scope', 'Names and scope', 'A name only exists once it''s been created, exactly as spelled.', '## What it is

Python only recognises a name once something has assigned it - and assigning to a name anywhere inside a function makes Python treat it as local for the whole function.

## What it looks like when it goes wrong

```
NameError: name ''x'' is not defined
UnboundLocalError: cannot access local variable ''x'' where it is not associated with a value
```

## How to spot it

Compare the name letter-by-letter against where it''s created, and check whether it''s assigned anywhere else in the same function.

## How to fix it

Fix the typo, or add `global name` if the function genuinely needs to update a module-level variable.

## Try it

```python run
count = 0

def increment():
    global count
    count += 1
    return count

print(increment())
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('types-and-conversion', 'Types and conversion', 'Values have types, and some operations need matching types.', '## What it is

Every value has a type (`str`, `int`, `float`...). Some operators behave differently - or refuse to work at all - depending on the types involved.

## What it looks like when it goes wrong

```
TypeError: can only concatenate str (not "int") to str
ValueError: invalid literal for int() with base 10: ''3.5''
```

## How to spot it

Check the types of the values either side of an operator, especially `+`.

## How to fix it

Convert explicitly with `str()`, `int()`, or `float()` as needed.

## Try it

```python run
age = 17
print("Age: " + str(age))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('indexing', 'Indexing', 'A list of length n has valid indexes 0 through n - 1.', '## What it is

List and string positions are counted from `0`. The last valid index is `len(x) - 1`.

## What it looks like when it goes wrong

```
IndexError: list index out of range
```

## How to spot it

Check the index against the list''s actual length, especially at the start and end.

## How to fix it

Use `len(x) - 1` for the last item, and guard against empty sequences.

## Try it

```python run
items = [10, 20, 30]
print(items[len(items) - 1])
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('dictionaries', 'Dictionaries', 'dict[key] crashes if the key is missing; .get() does not.', '## What it is

A dictionary looks up values by key. `d[key]` crashes if the key isn''t present; `d.get(key, default)` doesn''t.

## What it looks like when it goes wrong

```
KeyError: ''colour''
```

## How to spot it

Check whether the key being looked up is guaranteed to exist.

## How to fix it

Use `.get(key, default)` when the key might be missing.

## Try it

```python run
colours = {"apple": "red"}
print(colours.get("banana", "unknown"))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('zero-division-and-guards', 'Dividing by zero (and guarding against it)', 'Check a count isn''t zero before you divide by it.', '## What it is

Dividing (or using `%`) by zero always crashes in Python.

## What it looks like when it goes wrong

```
ZeroDivisionError: division by zero
```

## How to spot it

Look at what''s on the right of `/` or `%` - could it ever be zero? An empty list''s length is the classic case.

## How to fix it

Add a guard: check the value before dividing.

## Try it

```python run
scores = []
if len(scores) == 0:
    print("No scores yet")
else:
    print(sum(scores) / len(scores))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('input-validation', 'Validating input', 'Text from input() or elsewhere might not be in the shape you expect.', '## What it is

Any value that comes from outside your code - `input()`, a file, a user - might not be in the format your code assumes.

## What it looks like when it goes wrong

```
ValueError: invalid literal for int() with base 10: ''abc''
```

## How to spot it

Ask: what happens if this value isn''t what I expect?

## How to fix it

Convert carefully (e.g. via `float()` before `int()`), and consider checking the value before using it.

## Try it

```python run
text = "42"
print(int(text) * 2)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('return-values', 'Return values', 'A function without a return gives back None.', '## What it is

A function only gives back a value if it hits a `return` statement. Otherwise it implicitly returns `None`.

## What it looks like when it goes wrong

No error - just `None` where you expected a real value, or a crash later when something tries to use that `None`.

## How to spot it

If a function''s result always seems to be `None`, check every path through it for a `return`.

## How to fix it

Add the missing `return`.

## Try it

```python run
def add(a, b):
    return a + b

print(add(2, 3))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('function-calls', 'Function calls and arguments', 'A call must supply exactly the arguments the definition expects.', '## What it is

A function''s parameter list is a contract - every call must match it (unless defaults are used).

## What it looks like when it goes wrong

```
TypeError: greet() missing 1 required positional argument: ''last_name''
```

## How to spot it

Compare the `def` line to every place the function is called or tested.

## How to fix it

Add or remove parameters so the definition matches how it''s actually used.

## Try it

```python run
def greet(first_name, last_name):
    return "Hello, " + first_name + " " + last_name

print(greet("Ada", "Lovelace"))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('off-by-one', 'Off-by-one errors', 'Loops and ranges that stop one step too early or too late.', '## What it is

A loop, range or boundary check that''s out by exactly one - the most common logic bug in programming.

## What it looks like when it goes wrong

No error at all - just a result that''s slightly wrong, often missing the first or last item.

## How to spot it

Test with the smallest possible input by hand and check the first and last values a loop actually touches.

## How to fix it

Adjust the range, comparison operator, or starting value so the boundary is handled correctly.

## Try it

```python run
for i in range(1, 5):
    print(i)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('range-function', 'How range() works', 'range(a, b) includes a but stops before b.', '## What it is

`range(a, b)` produces `a, a+1, ..., b-1` - it always stops one short of `b`.

## What it looks like when it goes wrong

A loop that should include the last number doesn''t.

## How to spot it

Print `list(range(a, b))` for small numbers and check what''s actually in it.

## How to fix it

Use `range(a, b + 1)` when you need `b` included.

## Try it

```python run
print(list(range(1, 5)))
print(list(range(1, 6)))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('integer-vs-float-division', 'Integer vs float division', '/ gives the exact result; // rounds down and discards the remainder.', '## What it is

`/` always gives the exact, possibly-fractional result. `//` rounds down to a whole number.

## What it looks like when it goes wrong

No error - just a result missing its fractional part.

## How to spot it

Test with numbers that don''t divide evenly.

## How to fix it

Use `/` when you need the exact value, `//` only when you deliberately want to discard the remainder.

## Try it

```python run
print(7 / 2)
print(7 // 2)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('operator-precedence', 'Operator precedence', 'Multiplication and division happen before addition and subtraction.', '## What it is

Python follows the normal maths order of operations unless brackets say otherwise.

## What it looks like when it goes wrong

No error - just a calculation that doesn''t match what you meant.

## How to spot it

Work through the calculation by hand, following the actual order Python would use.

## How to fix it

Add brackets to make the intended order explicit.

## Try it

```python run
a, b = 4, 6
print((a + b) / 2)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('boolean-logic', 'and, or, and boolean logic', 'and needs both sides true; or needs just one.', '## What it is

`and` is true only if both sides are true. `or` is true if either side is true.

## What it looks like when it goes wrong

A validator accepts things it shouldn''t (or rejects things it shouldn''t).

## How to spot it

Check every `or` in a validator - would `and` be more correct?

## How to fix it

Swap `or` for `and` (or vice versa) to match the intended rule.

## Try it

```python run
name = "ada"
print(3 <= len(name) <= 20)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('loops-and-return', 'Loops and return', 'return exits the function immediately, from wherever it is.', '## What it is

`return` ends the function right away. Placed inside a loop by mistake, it can end a search after just one item.

## What it looks like when it goes wrong

A search stops too early, missing items later in the loop.

## How to spot it

Check a `return`''s indentation - is it inside the loop, or after it?

## How to fix it

Move the `return` to the correct indentation level.

## Try it

```python run
def find_first_even(nums):
    for n in nums:
        if n % 2 == 0:
            return n
    return None

print(find_first_even([1, 3, 4, 5]))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('accumulators', 'Accumulators', 'An accumulator needs resetting at the start of each new thing it sums.', '## What it is

An accumulator variable builds up a running total. It needs to start fresh whenever a new total should begin.

## What it looks like when it goes wrong

Totals creep upward, adding onto the previous one instead of starting over.

## How to spot it

Check where the accumulator is reset to its starting value - outside the loop, or inside it?

## How to fix it

Move the reset inside the loop that should restart it each time.

## Try it

```python run
for lst in [[1, 2], [3, 4]]:
    total = 0
    for n in lst:
        total += n
    print(total)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('loop-termination', 'Loop termination', 'Every while loop needs something that moves its condition towards false.', '## What it is

A `while` loop keeps running until its condition becomes false - something inside it must actually change that condition.

## What it looks like when it goes wrong

The run is stopped for taking too long - a classic infinite loop.

## How to spot it

Find the line that updates the condition''s variable. If there isn''t one, that''s the bug.

## How to fix it

Add the missing update (like `n -= 1`).

## Try it

```python run
n = 3
while n > 0:
    print(n)
    n -= 1
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('shadowing-builtins', 'Shadowing built-ins', 'Naming a variable sum or list hides the built-in function of the same name.', '## What it is

Python lets you name a variable the same as a built-in function, but doing so hides the built-in for the rest of that scope.

## What it looks like when it goes wrong

```
TypeError: ''int'' object is not callable
```

## How to spot it

If a `TypeError` says something isn''t callable, check if a variable has shadowed a built-in name.

## How to fix it

Rename the variable to something that isn''t a built-in function name.

## Try it

```python run
numbers = [1, 2, 3]
print(sum(numbers))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('mutating-while-iterating', 'Mutating while iterating', 'Changing a list or dict while looping over it can skip items or crash.', '## What it is

Adding or removing items from a collection while iterating over it directly can cause skipped items (lists) or a crash (dicts).

## What it looks like when it goes wrong

```
RuntimeError: dictionary changed size during iteration
```

Or, for lists: items are silently skipped with no error at all.

## How to spot it

Check whether the loop you''re modifying is the same collection you''re looping over.

## How to fix it

Build a new collection (e.g. with a list comprehension) or loop over a copy (`list(d.keys())`).

## Try it

```python run
nums = [1, -2, -3, 4]
print([n for n in nums if n >= 0])
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('string-methods', 'String methods and case', 'Character comparisons are case-sensitive.', '## What it is

`''A'' == ''a''` is `False` - comparisons are case-sensitive unless you normalise case yourself.

## What it looks like when it goes wrong

No error - just uppercase (or lowercase) input silently not matching.

## How to spot it

Test with a mix of uppercase and lowercase input.

## How to fix it

Use `.lower()` or `.upper()` on both sides before comparing.

## Try it

```python run
print("A".lower() in "aeiou")
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('mutable-defaults', 'Mutable default arguments', 'A default list or dict is created once, not fresh on every call.', '## What it is

A default argument value is evaluated exactly once, when `def` runs - not fresh on every call.

## What it looks like when it goes wrong

A list (or dict) "remembers" items from previous calls that didn''t supply their own.

## How to spot it

Check any default value that''s a list, dict, or other mutable object.

## How to fix it

Default to `None`, and create the real empty value inside the function body.

## Try it

```python run
def add_item(item, basket=None):
    if basket is None:
        basket = []
    basket.append(item)
    return basket

print(add_item("apple"))
print(add_item("banana"))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('aliasing-and-copying', 'Aliasing and copying', 'Assigning a list to a new name does not copy it.', '## What it is

`b = a` makes `b` another name for the exact same list object - not a copy.

## What it looks like when it goes wrong

Changing one variable unexpectedly changes another.

## How to spot it

Ask: do I need a genuinely separate list, or just another name for the same one?

## How to fix it

Use `.copy()`, `list(...)`, or a comprehension to create an independent list.

## Try it

```python run
original = [1, 2, 3]
copy = original.copy()
copy[0] = 99
print(original)
print(copy)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('recursion', 'Recursion and base cases', 'Every recursive function needs a condition where it stops calling itself.', '## What it is

A recursive function calls itself with a smaller version of the problem, until a base case stops the chain.

## What it looks like when it goes wrong

```
RecursionError: maximum recursion depth exceeded
```

## How to spot it

Check for a condition that returns without calling itself again.

## How to fix it

Add the missing base case.

## Try it

```python run
def count_down(n):
    if n <= 0:
        print("Done!")
        return
    print(n)
    count_down(n - 1)

count_down(3)
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('binary-search', 'Binary search bounds', 'The search range must shrink every pass, or it can loop forever.', '## What it is

Binary search repeatedly halves a sorted range until it finds the target or the range is empty.

## What it looks like when it goes wrong

The search never finishes when the target isn''t present - the range stops shrinking.

## How to spot it

Trace through a search for a missing value by hand, checking the bounds actually move each pass.

## How to fix it

Move bounds past `mid` (`mid + 1` / `mid - 1`), not onto it.

## Try it

```python run
def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

print(binary_search([1, 3, 5, 7], 5))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('closures', 'Closures and late binding', 'A lambda looks up a loop variable when called, not when created.', '## What it is

Functions created inside a loop share the same loop variable - they don''t each get a frozen copy of its value at creation time.

## What it looks like when it goes wrong

Every function created in the loop seems to return the same (final) value.

## How to spot it

Check whether a value used inside a lambda or nested function comes from an enclosing loop variable.

## How to fix it

Capture the current value with a default argument: `lambda x=x: ...`.

## Try it

```python run
makers = [lambda i=i: i for i in range(3)]
print([m() for m in makers])
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('iterators-and-generators', 'Iterators and generators', 'A generator can only be stepped through once.', '## What it is

A generator expression produces values lazily and doesn''t remember them - once consumed, it''s exhausted.

## What it looks like when it goes wrong

Listing the same generator a second time gives an empty result.

## How to spot it

Check whether something that needs reading more than once is a generator or a list.

## How to fix it

Use a list comprehension `[...]` instead of a generator expression `(...)` if you need to iterate more than once.

## Try it

```python run
evens = [n for n in range(10) if n % 2 == 0]
print(list(evens))
print(list(evens))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('floating-point', 'Floating-point precision', 'Most decimal fractions cannot be represented exactly in binary.', '## What it is

`float` values are stored in binary, and most decimal fractions (like 0.1) can''t be represented exactly - leading to tiny rounding errors.

## What it looks like when it goes wrong

`0.1 + 0.2 == 0.3` is `False` - an exact-equality check between floats silently fails.

## How to spot it

Any `==` comparison between floats is suspect.

## How to fix it

Use `math.isclose(a, b)` instead of `==`.

## Try it

```python run
import math
print(0.1 + 0.2 == 0.3)
print(math.isclose(0.1 + 0.2, 0.3))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('sorting', 'Sorting', 'sorted() defaults to ascending order.', '## What it is

`sorted()` arranges items smallest-to-largest by default, using `key` to decide what to compare.

## What it looks like when it goes wrong

Taking the "top" items after sorting actually gives the lowest ones.

## How to spot it

Check whether `reverse=True` is needed for what you actually want.

## How to fix it

Add `reverse=True` for descending order.

## Try it

```python run
scores = [10, 30, 20]
print(sorted(scores, reverse=True))
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('exception-handling', 'Exception handling', 'A bare except: hides every error, including genuine bugs.', '## What it is

`try`/`except` lets you handle specific, expected errors gracefully - but a bare `except:` catches everything, including mistakes you never intended to handle.

## What it looks like when it goes wrong

A function silently returns the wrong thing (often `None`) instead of crashing where the real mistake is.

## How to spot it

Look for bare `except:` clauses, especially around code that otherwise looks correct.

## How to fix it

Catch only the specific exception types you expect.

## Try it

```python run
try:
    result = 10 / 0
except ZeroDivisionError:
    print("Can''t divide by zero")
```');
INSERT INTO bh_concepts (slug, title, summary, lesson_md) VALUES ('identity-vs-equality', 'is vs ==', '== compares values; is compares identity (the exact same object).', '## What it is

`==` asks "do these have the same value?". `is` asks "are these the exact same object in memory?".

## What it looks like when it goes wrong

Two lists (or other objects) with identical contents compare as not equal when checked with `is`.

## How to spot it

Check whether `is` is being used where a value comparison (`==`) was actually meant.

## How to fix it

Use `==` for value comparisons; reserve `is` for `None` checks or genuine identity checks.

## Try it

```python run
a = [1, 2, 3]
b = [1, 2, 3]
print(a == b)
print(a is b)
```');

