INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-brackets', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Wrong Brackets', 9, 2, NULL, 'runtime', '`shout(word)` should return `word` in uppercase.

Example: `shout("hello")` should return `"HELLO"`.', 'def shout(word):
    result = word.upper[]
    return result
', 'def shout(word):
    result = word.upper()
    return result
', 'function', 'shout', '`()`, `[]` and `{}` all mean different things in Python: calling, indexing, and sets/dicts respectively. Using the wrong bracket type usually still runs - it just does something else entirely, or crashes with a type error.', 'When calling a method or function, it''s always round brackets `()`, even with nothing inside them.', NULL, 'published', '1dded55d171d9ca033e6b09f4b052f442f49ba0de67f5f4fbedc5484e6a8dcdf', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 1, 'shout("hello")', '(''hello'',)', NULL, NULL, 'returns', '"HELLO"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 2, 'shout("Python")', '(''Python'',)', NULL, NULL, 'returns', '"PYTHON"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 3, 'shout("")', '('''',)', NULL, NULL, 'returns', '""', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 1, 'This crashes with a `TypeError` about something not being subscriptable - a clue about which bracket is wrong.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 2, 'Calling a method (like `.upper`) and indexing into something use different brackets. Which one is this?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 3, 'Change `word.upper[]` to `word.upper()`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'bracket-types'), 'Square brackets `[]` are for indexing; round brackets `()` call a function or method. `.upper` is a method, so it needs `()`.', 'Change `[]` to `()`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-brackets'), (SELECT id FROM bh_concepts WHERE slug = 'bracket-types'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('unfinished-function', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Unfinished Function', 10, 1, NULL, 'syntax', '`square(n)` should return `n` multiplied by itself.

Example: `square(4)` should return `16`.', 'def square n:
    return n * n
', 'def square(n):
    return n * n
', 'function', 'square', 'A function definition always follows the same shape: `def`, a name, parentheses around the parameters, then a colon. Missing any one of those pieces means Python can''t parse the line at all.', 'Check every `def` line has the full shape: `def name(params):`.', NULL, 'published', 'f456cd30cd94daf0c3da428fe63d1a3fb593d3534d590ab53dfb15cd3f9d136b', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 1, 'square(4)', '(4,)', NULL, NULL, 'returns', '16', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 2, 'square(0)', '(0,)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 3, 'square(-3)', '(-3,)', NULL, NULL, 'returns', '9', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 1, 'This is a syntax error on the `def` line itself.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 2, 'Every function definition needs its parameters wrapped in a specific kind of bracket.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 3, 'Wrap `n` in parentheses: `def square(n):`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), 1, 1, 1, 'syntax', (SELECT id FROM bh_concepts WHERE slug = 'function-syntax'), 'The function''s parameters need to be inside parentheses - `def square n:` is missing them.', 'Change `def square n:` to `def square(n):`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unfinished-function'), (SELECT id FROM bh_concepts WHERE slug = 'function-syntax'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('mystery-name', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Mystery Name', 1, 1, NULL, 'runtime', '`greet(name)` should return a greeting like `"Hello, Ada!"`.

Example: `greet("Ada")` should return `"Hello, Ada!"`.', 'def greet(name):
    message = "Hello, " + nmae + "!"
    return message
', 'def greet(name):
    message = "Hello, " + name + "!"
    return message
', 'function', 'greet', 'Python only recognises a name once it''s been created - it doesn''t guess what you meant. A typo in a variable name looks right to the eye but is a completely different, undefined name to Python, so it crashes as soon as that line runs.', 'When you see a `NameError`, compare the named variable letter-by-letter against where it was created.', NULL, 'published', '8fa305c3f67692f3251ec0c811c8fc4e5621645d9217c298a69935975e20e568', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 1, 'greet("Ada")', '(''Ada'',)', NULL, NULL, 'returns', '"Hello, Ada!"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 2, 'greet("Bo")', '(''Bo'',)', NULL, NULL, 'returns', '"Hello, Bo!"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 3, 'greet("")', '('''',)', NULL, NULL, 'returns', '"Hello, !"', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 4, 'greet("Sam")', '(''Sam'',)', NULL, NULL, 'returns', '"Hello, Sam!"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 1, 'The code runs and then crashes - that''s a `NameError`. Read the traceback''s last line first.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 2, 'Look at the variable used inside the message. Compare its spelling to the function''s parameter.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 3, '`nmae` should be `name` - fix the typo so it matches the parameter exactly.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), '`nmae` is never defined - it''s a typo for the parameter `name`, so Python raises a `NameError` the moment this line runs.', 'Change `nmae` to `name`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mystery-name'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('text-plus-number', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Text Plus Number', 2, 1, NULL, 'runtime', '`describe_age(age)` should return a string like `"Age: 17"`.

Example: `describe_age(17)` should return `"Age: 17"`.', 'def describe_age(age):
    return "Age: " + age
', 'def describe_age(age):
    return "Age: " + str(age)
', 'function', 'describe_age', 'Python''s `+` operator means something different depending on the types either side of it: joining for two strings, addition for two numbers. Mixing a string and a number directly leaves Python unable to decide which you meant.', 'Before joining a value to a string with `+`, check its type - numbers need `str()` first.', NULL, 'published', 'f7b12336f99fc507d5bc05fddefc57bc8d25268c01ee6c6b53c45ee8101aab0a', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 1, 'describe_age(17)', '(17,)', NULL, NULL, 'returns', '"Age: 17"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 2, 'describe_age(5)', '(5,)', NULL, NULL, 'returns', '"Age: 5"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 3, 'describe_age(0)', '(0,)', NULL, NULL, 'returns', '"Age: 0"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 1, 'This crashes with a `TypeError` about joining two things together.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 2, '`age` is a number, but `+` between a string and a number is not allowed directly.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 3, 'Wrap `age` in `str(...)` before joining it to the string.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`+` between a string and an `int` is not allowed - `age` needs converting to a string first.', 'Use `str(age)` instead of `age`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('past-the-end', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Past the End', 3, 2, NULL, 'runtime', '`last_item(items)` should return the last item in the list `items`.

Example: `last_item([1, 2, 3])` should return `3`.', 'def last_item(items):
    return items[len(items)]
', 'def last_item(items):
    return items[len(items) - 1]
', 'function', 'last_item', 'A list of length `n` has valid indexes `0` through `n - 1`. `len(items)` is one more than the last valid index, so using it directly always lands one step past the end.', 'Whenever you index with `len(...)`, check whether you need to subtract 1.', NULL, 'published', 'caad02ab90ce55e08a5e7e723ad378f40038bbe7b3e5ca04cd44ab2f0e4d7032', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 1, 'last_item([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 2, 'last_item([5])', '([5],)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 3, 'last_item([10, 20])', '([10, 20],)', NULL, NULL, 'returns', '20', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 1, 'This crashes with an `IndexError` - the position asked for is out of range.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 2, 'If a list has 3 items, what are its valid index positions? Does `len(items)` itself point at a real item?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 3, 'Use `items[len(items) - 1]` instead of `items[len(items)]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), 'Valid indexes run from `0` to `len(items) - 1`. `items[len(items)]` is one position past the last real item.', 'Subtract 1: `items[len(items) - 1]`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), (SELECT id FROM bh_concepts WHERE slug = 'indexing'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('missing-key', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Missing Key', 4, 2, NULL, 'runtime', '`get_colour(fruit)` should return the colour of `fruit`, or `"unknown"` if it isn''t in the list.

Example: `get_colour("apple")` should return `"red"`.', 'def get_colour(fruit):
    colours = {"apple": "red", "banana": "yellow"}
    return colours[fruit]
', 'def get_colour(fruit):
    colours = {"apple": "red", "banana": "yellow"}
    return colours.get(fruit, "unknown")
', 'function', 'get_colour', '`dict[key]` crashes with `KeyError` if the key isn''t present. `.get(key, default)` checks safely and returns the default instead, which is almost always what you want when the key might be missing.', 'Any time you index a dictionary with something that didn''t come from iterating its own keys, consider `.get()` instead.', NULL, 'published', '7a07ad9f1998bcfe1fc61746b75d145ec28501af4c6c9e5b60b9e8cf76785710', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 1, 'get_colour("apple")', '(''apple'',)', NULL, NULL, 'returns', '"red"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 2, 'get_colour("banana")', '(''banana'',)', NULL, NULL, 'returns', '"yellow"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 3, 'get_colour("grape")', '(''grape'',)', NULL, NULL, 'returns', '"unknown"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 1, 'This crashes with a `KeyError` - the dictionary was asked for something it doesn''t have.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 2, 'There''s a dictionary method that returns a default value instead of crashing when a key is missing.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 3, 'Use `colours.get(fruit, "unknown")` instead of `colours[fruit]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 1, 3, 3, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'), '`colours[fruit]` crashes if `fruit` isn''t a key already in the dictionary.', 'Use `.get(fruit, "unknown")` to supply a default instead of crashing.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('divide-by-nothing', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Divide by Nothing', 5, 2, NULL, 'runtime', '`average(nums)` should return the mean of the numbers in `nums`, or `0` if the list is empty.

Example: `average([2, 4, 6])` should return `4`.', 'def average(nums):
    return sum(nums) / len(nums)
', 'def average(nums):
    if len(nums) == 0:
        return 0
    return sum(nums) / len(nums)
', 'function', 'average', 'Dividing by zero always crashes in Python. Any time a divisor comes from a count that could be zero - like the length of a list - it needs a guard before the division runs.', 'Ask "could this count ever be zero?" for every division, and test with an empty input to check.', NULL, 'published', '6a947c268ccf7c3d800b60c4a85dfab8ae80bfd21a9285f414996e3547dc3211', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'divide-by-nothing'), 1, 'average([2, 4, 6])', '([2, 4, 6],)', NULL, NULL, 'returns', '4', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'divide-by-nothing'), 2, 'average([10])', '([10],)', NULL, NULL, 'returns', '10', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'divide-by-nothing'), 3, 'average([])', '([],)', NULL, NULL, 'returns', '0', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'divide-by-nothing'), 1, 'This crashes with a `ZeroDivisionError` on at least one test - which input might make `len(nums)` zero?');
