INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'divide-by-nothing'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'zero-division-and-guards'), 'If `nums` is empty, `len(nums)` is `0` and the division crashes.', 'Guard against an empty list before dividing.');
