INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('nothing-returned', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Nothing Returned', 7, 1, NULL, 'runtime', '`add(a, b)` should return the sum of `a` and `b`.

Example: `add(2, 3)` should return `5`.', 'def add(a, b):
    total = a + b
', 'def add(a, b):
    total = a + b
    return total
', 'function', 'add', 'A function that doesn''t hit a `return` statement gives back `None` automatically - computing a value inside a function does nothing on its own unless it''s returned.', 'If a function''s result always seems to be `None`, check it actually has a `return` on the path that runs.', NULL, 'published', 'cb7de63f179a96347c859f484fc71d81bfe82866e7a0278e0487285e7d944785', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nothing-returned'), 1, 'add(2, 3)', '(2, 3)', NULL, NULL, 'returns', '5', 'exact', 0);
