INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-that-looked-like-a-number'), 3, 'Convert `price_text` with `int(...)` before using it in the calculation.');
