INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-that-looked-like-a-number'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-number-of-arguments', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Wrong Number of Arguments', 10, 2, NULL, 'runtime', '`greet(first_name, last_name)` should return a greeting using both names.

Example: `greet("Ada", "Lovelace")` should return `"Hello, Ada Lovelace!"`.', 'def greet(name):
    return "Hello, " + name + "!"
', 'def greet(first_name, last_name):
    return "Hello, " + first_name + " " + last_name + "!"
', 'function', 'greet', 'A function''s parameter list is a contract: every call must supply exactly the arguments it''s defined to accept (unless defaults are used). A mismatch between how a function is defined and how it''s meant to be used is a `TypeError` waiting to happen.', 'When a `TypeError` mentions argument counts, compare the `def` line to every place the function is called or tested.', NULL, 'published', 'ca942b4f30ef35e8da48add6eea2264f5a7841b772f47b242f43135b8c443a4d', NOW());
