INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sum-to-n-off-by-one'), 2, 'Look at the `range()` call. Which numbers does `range(1, n)` actually produce?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sum-to-n-off-by-one'), 3, '`range` stops one short of its second value. You need the loop to reach `n` itself.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sum-to-n-off-by-one'), 1, 3, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), '`range(1, n)` stops at `n - 1`, so `n` is never added.', 'Use `range(1, n + 1)`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sum-to-n-off-by-one'), (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'));
