INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('fence-posts', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Fence Posts', 2, 2, NULL, 'logic', 'A straight fence needs one post at the start, then one more post per section. `posts_needed(sections)` should return the number of posts needed for a fence with that many sections.

Example: `posts_needed(4)` should return `5`.', 'def posts_needed(sections):
    return sections
', 'def posts_needed(sections):
    return sections + 1
', 'function', 'posts_needed', 'This is the classic "fencepost" off-by-one: counting the gaps (sections) isn''t the same as counting the boundaries between them (posts). Drawing a tiny example (1 or 2 sections) on paper makes the relationship obvious.', 'For anything involving counting items versus counting the gaps between them, sketch a tiny example by hand first.', 'If a fence has 4 sections, how many posts does it need? Write your answer down before running anything.', 'published', '4fff50b46110b3c2d452ba52d1b79b80c4a34859cf195784e062178f2c4aa7fb', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 1, 'posts_needed(4)', '(4,)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 2, 'posts_needed(1)', '(1,)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 3, 'posts_needed(0)', '(0,)', NULL, NULL, 'returns', '1', 'exact', 1);
