INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 1, 'This runs fine but gives the wrong number - count the posts for a tiny fence by hand (try 1 section) and compare.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 2, 'A fence with 1 section has posts at both ends - that''s 2 posts, not 1.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 3, 'Add 1 to `sections`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fence-posts'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), 'The number of posts is always one more than the number of sections (there''s a post at both ends), but this just returns the section count.', 'Return `sections + 1`.');
