INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('half-a-result', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Half a Result', 3, 2, NULL, 'logic', '`average_two(a, b)` should return the exact average of `a` and `b`.

Example: `average_two(3, 4)` should return `3.5`.', 'def average_two(a, b):
    return (a + b) // 2
', 'def average_two(a, b):
    return (a + b) / 2
', 'function', 'average_two', '`/` always gives the exact, possibly-fractional result. `//` rounds down to a whole number, discarding whatever came after the decimal point. They look almost identical but behave very differently.', 'Test division with numbers that don''t divide evenly - that''s when `//` versus `/` shows up clearly.', NULL, 'published', 'a9633fd518a8aeb7c7917a8674129cbc088829abff7c08e28e548d9aa302bb12', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'half-a-result'), 1, 'average_two(3, 4)', '(3, 4)', NULL, NULL, 'returns', '3.5', 'exact', 0);
