INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'half-a-result'), 3, 'average_two(1, 2)', '(1, 2)', NULL, NULL, 'returns', '1.5', 'exact', 1);
