INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('average-trouble', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Average Trouble', 4, 2, NULL, 'logic', '`average_two(a, b)` should return the average of `a` and `b`.

Example: `average_two(4, 6)` should return `5`.', 'def average_two(a, b):
    return a + b / 2
', 'def average_two(a, b):
    return (a + b) / 2
', 'function', 'average_two', 'Python follows the normal maths order of operations: multiplication and division happen before addition and subtraction, unless brackets say otherwise. `a + b / 2` means `a + (b / 2)`, not `(a + b) / 2`.', 'When a calculation mixes `+`/`-` with `*`/`/`, add brackets to make the intended order explicit, even when you''re confident of the rules.', NULL, 'published', 'fe253e7f3d3006e39ddf763304d23027a7b027e4bc7bda4bbcf4232bc783384c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 1, 'average_two(4, 6)', '(4, 6)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 2, 'average_two(0, 10)', '(0, 10)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 3, 'average_two(2, 2)', '(2, 2)', NULL, NULL, 'returns', '2', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 1, 'This runs fine but gives the wrong answer for most inputs - check `average_two(4, 6)` by hand.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 2, 'Without brackets, which happens first: the division, or the addition?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 3, 'Wrap `a + b` in brackets so it happens before the division: `(a + b) / 2`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'), 'Without brackets, `/` happens before `+`, so this divides only `b` by 2 instead of the whole sum.', 'Add brackets: `(a + b) / 2`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-trouble'), (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('and-or-or', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'And or Or', 5, 2, NULL, 'logic', 'A valid username is between 3 and 20 characters long (inclusive). `is_valid_username(name)` should return `True` or `False` accordingly.

Example: `is_valid_username("al")` should return `False` (too short).', 'def is_valid_username(name):
    return len(name) >= 3 or len(name) <= 20
', 'def is_valid_username(name):
    return len(name) >= 3 and len(name) <= 20
', 'function', 'is_valid_username', '`or` is true if *either* side is true; `and` needs *both*. A validator that should enforce a range on both ends almost always needs `and`, since `or` lets almost everything through.', 'When a validator seems to accept things it shouldn''t, check every `or` - would `and` be stricter and more correct?', NULL, 'published', 'e172c3cadc1b2707b1b1e9e6fb2f7873ee83bbb7759c912a0c31be6620a6f713', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'and-or-or'), 1, 'is_valid_username("ada")', '(''ada'',)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'and-or-or'), 2, 'is_valid_username("al")', '(''al'',)', NULL, NULL, 'returns', 'False', 'exact', 0);
