INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shadowed'), (SELECT id FROM bh_concepts WHERE slug = 'shadowing-builtins'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('modify-while-looping', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Modify While Looping', 11, 3, NULL, 'logic', '`remove_negatives(nums)` should return `nums` with every negative number removed.

Example: `remove_negatives([1, -2, -3, 4])` should return `[1, 4]`.', 'def remove_negatives(nums):
    for n in nums:
        if n < 0:
            nums.remove(n)
    return nums
', 'def remove_negatives(nums):
    return [n for n in nums if n >= 0]
', 'function', 'remove_negatives', 'When you remove an item from a list mid-iteration, everything after it shifts one position earlier - but the loop''s position doesn''t shift back to match, so it can silently skip the next item. Building a new list avoids the problem entirely.', 'Never remove items from a list (or dict) while iterating over that same list - build a new one or iterate over a copy instead.', NULL, 'published', '6e21ff18e4f4db554cf2be839ecc9c7bf352e709b40e3fdd4b1b60a5ae152a2c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 1, 'remove_negatives([1, -2, -3, 4])', '([1, -2, -3, 4],)', NULL, NULL, 'returns', '[1, 4]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 2, 'remove_negatives([-1, -2, -3])', '([-1, -2, -3],)', NULL, NULL, 'returns', '[]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 3, 'remove_negatives([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '[1, 2, 3]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 1, 'Try a list with two negative numbers next to each other - does it remove both?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 2, 'Removing an item from a list while you''re iterating over it shifts everything after it along by one - which can make the loop skip the very next item.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 3, 'Build a new list with a list comprehension instead of removing items from the original while looping over it.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), 1, 2, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutating-while-iterating'), 'Removing items from `nums` while looping over it shifts the remaining items'' positions, so the loop can skip the item right after a removed one.', 'Build a new filtered list instead, e.g. with a list comprehension.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'modify-while-looping'), (SELECT id FROM bh_concepts WHERE slug = 'mutating-while-iterating'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('case-matters', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Case Matters', 12, 2, NULL, 'logic', '`count_vowels(text)` should count how many vowels (a, e, i, o, u) are in `text`, regardless of case.

Example: `count_vowels("APPLE")` should return `2`.', 'def count_vowels(text):
    count = 0
    for ch in text:
        if ch in "aeiou":
            count += 1
    return count
', 'def count_vowels(text):
    count = 0
    for ch in text:
        if ch.lower() in "aeiou":
            count += 1
    return count
', 'function', 'count_vowels', 'Character comparisons in Python are case-sensitive - `''A'' == ''a''` is `False`. Converting both sides to the same case with `.lower()` (or `.upper()`) before comparing handles this cleanly.', 'When comparing text, test with a mix of uppercase and lowercase input to check case is handled the way you expect.', NULL, 'published', '7a1c8f67b9fb05dce5c115d2bc58819322018a3c151152657a9ded20fd0d9a51', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 1, 'count_vowels("APPLE")', '(''APPLE'',)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 2, 'count_vowels("hello")', '(''hello'',)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 3, 'count_vowels("Why")', '(''Why'',)', NULL, NULL, 'returns', '0', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 1, 'This works for lowercase text, but try an all-uppercase word.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 2, '`"aeiou"` only contains lowercase letters. What happens when `ch` is uppercase?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 3, 'Compare `ch.lower()` against `"aeiou"` instead of `ch` directly.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'string-methods'), '`"aeiou"` only matches lowercase vowels, so uppercase ones like `''A''` are never counted.', 'Use `ch.lower() in "aeiou"`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-matters'), (SELECT id FROM bh_concepts WHERE slug = 'string-methods'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('infinite-descent', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Infinite Descent', 1, 3, NULL, 'runtime', '`factorial(n)` should return `n!` (n factorial): `n * (n-1) * (n-2) * ... * 1`.

Example: `factorial(5)` should return `120`. By definition, `factorial(0)` and `factorial(1)` both return `1`.', 'def factorial(n):
    return n * factorial(n - 1)
', 'def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)
', 'function', 'factorial', 'Recursive functions need two things: a base case that returns without recursing, and a recursive case that''s guaranteed to move closer to that base case. This function only has the recursive case, so it never stops - it just keeps calling itself with smaller and smaller numbers until Python gives up.', 'Whenever you write a recursive function, write the base case first and check the recursive call actually moves towards it.', 'What do you think happens when you run `factorial(5)`? Will it finish? Write down what you expect before you run it.', 'published', '8cda8441bd441b79d4348d243b274fe7f2358ded3914d0f00021ccb64686a5ad', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 1, 'factorial(5)', '(5,)', NULL, NULL, 'returns', '120', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 2, 'factorial(3)', '(3,)', NULL, NULL, 'returns', '6', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 3, 'factorial(1)', '(1,)', NULL, NULL, 'returns', '1', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 4, 'factorial(0)', '(0,)', NULL, NULL, 'returns', '1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 1, 'This one crashes with a `RecursionError` - the function keeps calling itself and never stops.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 2, 'Every recursive function needs a condition where it stops calling itself. Does this one have one?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 3, 'Add a base case: if `n <= 1`, return `1` directly, before the recursive call.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 1, 1, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'recursion'), 'There''s no base case, so `factorial` keeps calling itself with a smaller `n` forever, until Python''s recursion limit is hit.', 'Add `if n <= 1: return 1` before the recursive call.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), (SELECT id FROM bh_concepts WHERE slug = 'recursion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('shared-default', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Shared Default', 2, 3, NULL, 'logic', 'Each call to `add_item` should start from a fresh, empty basket unless one is given.

Expected output:
```
[''apple'']
[''banana'']
```', 'def add_item(item, basket=[]):
    basket.append(item)
    return basket

print(add_item("apple"))
print(add_item("banana"))
', 'def add_item(item, basket=None):
    if basket is None:
        basket = []
    basket.append(item)
    return basket

print(add_item("apple"))
print(add_item("banana"))
', 'script', NULL, 'A default argument value is evaluated exactly once, when `def` runs - not fresh on every call. For an immutable default like a number or string this never matters, but a mutable default like a list or dict gets shared and silently mutated across every call that relies on it.', 'Never use a mutable value (`[]`, `{}`, a class instance) as a default argument - use `None` and create the real default inside the function body instead.', 'Each call leaves out the `basket` argument. What do you expect the two printed lines to look like?', 'published', '2d78064811ca3aa88e97a29acd15016cb3925e5f55dce354e16f48535ea5d6b5', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 1, 'two separate calls stay separate', NULL, NULL, '', 'stdout', '"[''apple'']\\n[''banana'']\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 2, 'two separate calls stay separate (repeat check)', NULL, NULL, '', 'stdout', '"[''apple'']\\n[''banana'']\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 1, 'This runs without errors, but the second line printed isn''t what you''d expect from "start fresh each time".');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 2, 'A default argument value is created only once, when the function is defined - not fresh on every call. What kind of default value could that cause problems for?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 3, 'Use `basket=None` as the default, then create a new empty list inside the function if `basket is None`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 1, 1, 1, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'), 'The default list `[]` is created once when the function is defined, and reused across every call that doesn''t supply its own basket - so items pile up across calls instead of starting fresh.', 'Default to `None`, and create a new list inside the function when no basket is given.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('same-list-two-names', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Same List, Two Names', 3, 3, NULL, 'logic', 'Doubling a copy of a list should leave the original list unchanged.

Expected output:
```
[1, 2, 3]
[2, 4, 6]
```', 'original = [1, 2, 3]
doubled = original
for i in range(len(doubled)):
    doubled[i] = doubled[i] * 2
print(original)
print(doubled)
', 'original = [1, 2, 3]
doubled = original.copy()
for i in range(len(doubled)):
    doubled[i] = doubled[i] * 2
print(original)
print(doubled)
', 'script', NULL, 'Assigning a list to a new name doesn''t copy it - both names point at the exact same object in memory. Changing the contents through either name changes what both names see, which is surprising if you expected an independent copy.', 'If you need a genuinely separate list, use `.copy()`, `list(...)`, or a slice `[:]` - plain `=` never copies a list.', 'After `doubled = original`, are `original` and `doubled` separate lists, or two names for the same one? What do you expect printed?', 'published', '631841c23f9f6f2b0691361d6b266d14f96284af7059a436f2e28c82118db40d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 1, 'original stays untouched', NULL, NULL, '', 'stdout', '"[1, 2, 3]\\n[2, 4, 6]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 2, 'original stays untouched (repeat check)', NULL, NULL, '', 'stdout', '"[1, 2, 3]\\n[2, 4, 6]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 1, 'This runs fine, but check both printed lines - is the first one what you expected?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 2, '`doubled = original` doesn''t make a new list - it makes `doubled` another name for the exact same list.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 3, 'Use `original.copy()` (or `list(original)`) to make a genuinely separate list.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`doubled = original` makes `doubled` point at the same list object as `original`, so changing one through its index changes both.', 'Use `original.copy()` to create an independent list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('grid-surprise', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Grid Surprise', 4, 4, NULL, 'logic', 'Changing one cell of a grid should only affect that one cell.

Expected output:
```
[[1, 0, 0], [0, 0, 0], [0, 0, 0]]
```', 'grid = [[0] * 3] * 3
grid[0][0] = 1
print(grid)
', 'grid = [[0] * 3 for _ in range(3)]
grid[0][0] = 1
print(grid)
', 'script', NULL, 'Multiplying a list with `*` repeats references to the same object, not independent copies - this is harmless for immutable items like numbers, but for a list-of-lists, every "row" ends up being the exact same row, aliased three times over.', 'Never build a 2D grid with `[[...] * n] * m` - use a comprehension so each row is created fresh.', 'After `grid[0][0] = 1`, how many of the 9 cells do you expect to show `1`?', 'published', 'aad26edd514fa5f1814e44f59b8e304ebb026f46c2a966151563eef29a6686fc', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 1, 'only one cell changes', NULL, NULL, '', 'stdout', '"[[1, 0, 0], [0, 0, 0], [0, 0, 0]]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 2, 'only one cell changes (repeat check)', NULL, NULL, '', 'stdout', '"[[1, 0, 0], [0, 0, 0], [0, 0, 0]]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 1, 'Only one cell was changed in the code - but look at how many `1`s show up in the output.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 2, '`[[0] * 3] * 3` repeats the *same inner list* three times, not three independent lists.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 3, 'Use a list comprehension - `[[0] * 3 for _ in range(3)]` - to create three genuinely separate rows.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 1, 1, 1, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`[[0] * 3] * 3` makes a list containing the *same* inner list object three times, so changing one row through an index changes every row.', 'Build the rows with a list comprehension so each one is a separate list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('the-search-that-hangs', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'The Search That Hangs', 5, 4, NULL, 'logic', '`binary_search(items, target)` should return the index of `target` in the sorted list `items`, or `-1` if it isn''t there.

Example: `binary_search([1, 3, 5, 7, 9], 7)` should return `3`.', 'def binary_search(items, target):
    low, high = 0, len(items)
    while low < high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid
        else:
            high = mid
    return -1
', 'def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
', 'function', 'binary_search', 'Binary search relies on the search range shrinking every single pass. If a new bound is set to `mid` itself rather than one step past it, the range can stop shrinking entirely when the target isn''t in the list - looping forever instead of giving up.', 'For any loop meant to narrow down a range, check by hand that the range can''t get stuck at the same size pass after pass.', NULL, 'published', '9e3b4c7e6fad8345fca5c1ba78b0077225e6bfd6ce8c7cb151086b2c0ff07260', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 1, 'binary_search([1, 3, 5, 7, 9], 7)', '([1, 3, 5, 7, 9], 7)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 2, 'binary_search([1, 3, 5, 7, 9], 1)', '([1, 3, 5, 7, 9], 1)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 3, 'binary_search([1, 2], 5)', '([1, 2], 5)', NULL, NULL, 'returns', '-1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 1, 'At least one test gets stopped for taking too long - the search bounds aren''t narrowing down the way they should.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 2, 'When the target is smaller or larger than the middle item, how much does `low` or `high` actually move? Could `mid` ever equal `low` or `high` again on the next pass?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 3, 'Narrow the bounds past `mid`, not onto it: use `low = mid + 1` and `high = mid - 1`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 1, 7, 9, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'binary-search'), 'Setting `low = mid` or `high = mid` (instead of `mid + 1` / `mid - 1`) can leave the search bounds unchanged between passes, looping forever when the target isn''t present.', 'Move the bounds past `mid`: `low = mid + 1` and `high = mid - 1`, and start `high` at `len(items) - 1`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), (SELECT id FROM bh_concepts WHERE slug = 'binary-search'));
