INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('late-binding', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Late Binding', 6, 4, NULL, 'logic', 'Each function made in the loop should remember its *own* value of `i` at the time it was created.

Expected output:
```
[0, 1, 2]
```', 'makers = []
for i in range(3):
    makers.append(lambda: i)
print([m() for m in makers])
', 'makers = []
for i in range(3):
    makers.append(lambda i=i: i)
print([m() for m in makers])
', 'script', NULL, 'A closure remembers the *variable*, not the value it held at creation time. Since all three lambdas share the same loop variable `i`, and the loop has finished by the time any of them are called, they all see `i`''s final value. A default argument is evaluated once, at creation, which is how to capture the value instead.', 'If you create functions inside a loop that need to remember the loop variable''s value, capture it with a default argument: `lambda x=x: ...`.', 'Three lambdas are created, one per loop iteration. What do you expect calling all three, in order, to give?', 'published', '8416e56bc0e9651ca3521b3316d160fe0da0047e19b26c18758e39d4fbbf9561', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 1, 'each lambda remembers its own i', NULL, NULL, '', 'stdout', '"[0, 1, 2]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 2, 'each lambda remembers its own i (repeat check)', NULL, NULL, '', 'stdout', '"[0, 1, 2]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 1, 'All three results come out the same - but they were created with three different values of `i`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 2, 'A lambda looks up `i` in its enclosing scope *when it''s called*, not when it''s created - and there''s only one `i` variable, shared by the whole loop.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 3, 'Give the lambda its own parameter with a default: `lambda i=i: i`, capturing the current value at creation time.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 1, 3, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'closures'), 'The lambda doesn''t capture `i`''s value at creation time - it looks `i` up when called, by which point the loop has finished and `i` holds its final value for every lambda.', 'Use a default argument to capture the current value: `lambda i=i: i`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), (SELECT id FROM bh_concepts WHERE slug = 'closures'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('global-mistake', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Global Mistake', 7, 3, NULL, 'logic', '`record_score` should remember the highest score seen so far, across separate calls.

Expected output:
```
50
50
80
```', 'high_score = 0

def record_score(points):
    local_high = high_score
    if points > local_high:
        local_high = points
    return local_high

print(record_score(50))
print(record_score(30))
print(record_score(80))
', 'high_score = 0

def record_score(points):
    global high_score
    if points > high_score:
        high_score = points
    return high_score

print(record_score(50))
print(record_score(30))
print(record_score(80))
', 'script', NULL, 'Reading a global variable into a local one copies its current value - it doesn''t create a live link back to the original. Without `global`, any "updates" only change the local copy, which disappears when the function returns, leaving the real global untouched.', 'If a function needs to remember something between separate calls, it has to update a genuine global (with `global`) - a local copy resets every time.', 'Three scores are recorded in a row: 50, then 30, then 80. What do you expect printed each time?', 'published', 'caedc6ab358244af587b488d96946b0c5924de6e695916b41f6c24df03f054bf', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 1, 'high score persists across calls', NULL, NULL, '', 'stdout', '"50\\n50\\n80\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 2, 'high score persists across calls (repeat check)', NULL, NULL, '', 'stdout', '"50\\n50\\n80\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 1, 'The second line printed is lower than the first - but a *high* score should never go down.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 2, '`local_high` is a brand new local variable every call - does it actually update `high_score` for next time?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 3, 'Declare `global high_score` inside the function, and update `high_score` directly instead of a local copy.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), '`local_high` copies `high_score`''s value but never writes back to it, so the module-level `high_score` stays `0` forever and each call compares against that, not the real running high score.', 'Add `global high_score` and update `high_score` itself.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('used-up', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Used Up', 8, 4, NULL, 'logic', 'Listing the same filtered results twice should give the same answer both times.

Expected output:
```
[2, 4, 6]
[2, 4, 6]
```', 'def even_numbers(nums):
    return (n for n in nums if n % 2 == 0)

evens = even_numbers([1, 2, 3, 4, 5, 6])
print(list(evens))
print(list(evens))
', 'def even_numbers(nums):
    return [n for n in nums if n % 2 == 0]

evens = even_numbers([1, 2, 3, 4, 5, 6])
print(list(evens))
print(list(evens))
', 'script', NULL, 'Generators produce values lazily, one at a time, and don''t remember them afterwards - once consumed, they''re exhausted for good. A list holds all its values at once and can be read repeatedly, which is what''s needed here.', 'If something needs to be iterated over more than once, make sure it''s a list (or another reusable collection), not a one-shot generator.', '`list(evens)` is called twice on the same `evens`. What do you expect the second call to print?', 'published', 'e8c742acbb814da1a7833b8aa47913a2843a673df9c755f070d22d272c76c55d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 1, 'listing twice gives the same result both times', NULL, NULL, '', 'stdout', '"[2, 4, 6]\\n[2, 4, 6]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 2, 'listing twice gives the same result both times (repeat check)', NULL, NULL, '', 'stdout', '"[2, 4, 6]\\n[2, 4, 6]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 1, 'The second printed line is empty - but nothing was removed from `evens` on purpose.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 2, 'A generator expression `(... for ...)` only produces its values once, in one pass. What happens once every value has been read?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 3, 'Return a list comprehension `[...]` instead of a generator expression `(...)`, so it can be listed more than once.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'iterators-and-generators'), 'A generator can only be stepped through once - the first `list(evens)` consumes every value, so the second one has nothing left to give.', 'Use a list comprehension `[n for n in nums if ...]` instead, which can be read as many times as needed.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), (SELECT id FROM bh_concepts WHERE slug = 'iterators-and-generators'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('nearly-equal', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Nearly Equal', 9, 3, NULL, 'logic', '`adds_to_one(a, b, c)` should return `True` if the three numbers add up to (very close to) `1`.

Example: `adds_to_one(0.7, 0.2, 0.1)` should return `True`.', 'def adds_to_one(a, b, c):
    return a + b + c == 1.0
', 'import math

def adds_to_one(a, b, c):
    return math.isclose(a + b + c, 1.0)
', 'function', 'adds_to_one', 'Computers store `float` numbers in binary, and most decimal fractions (like 0.1) can''t be represented exactly in binary any more than 1/3 can be written exactly in decimal. The tiny rounding errors this creates mean exact equality (`==`) between floats is almost never the right check.', 'Never compare floats with `==` - use `math.isclose()` (or check the difference is smaller than a small tolerance) instead.', 'Do you expect `0.7 + 0.2 + 0.1` to be exactly equal to `1.0` in Python? Write down yes or no before running it.', 'published', '5bf2aab5c63b64dd7dd5e392024da80beda327a09b2f31a9996692ba4352993d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 1, 'adds_to_one(0.7, 0.2, 0.1)', '(0.7, 0.2, 0.1)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 2, 'adds_to_one(0.6, 0.3, 0.1)', '(0.6, 0.3, 0.1)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 3, 'adds_to_one(1, 1, 1)', '(1, 1, 1)', NULL, NULL, 'returns', 'False', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 1, 'The first test fails even though `0.7 + 0.2 + 0.1` really does equal 1 on paper.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 2, 'Computers store decimal fractions like `0.1` approximately, in binary - try printing `0.7 + 0.2 + 0.1` directly and look closely at the result.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 3, 'Use `math.isclose(a + b + c, 1.0)` instead of `==`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'floating-point'), 'Floating-point numbers can''t represent most decimal fractions exactly, so `0.1 + 0.2 + 0.7` comes out as something like `0.9999999999999999`, not exactly `1.0`.', 'Use `math.isclose(...)` to compare with a small tolerance instead of `==`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), (SELECT id FROM bh_concepts WHERE slug = 'floating-point'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('changing-while-iterating-dict', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Changing While Iterating', 10, 4, NULL, 'runtime', '`remove_zero_stock(stock)` should remove any item from the `stock` dictionary whose count is `0`, and return the dictionary.

Example: `remove_zero_stock({"pens": 0, "pencils": 5})` should return `{"pencils": 5}`.', 'def remove_zero_stock(stock):
    for item in stock:
        if stock[item] == 0:
            del stock[item]
    return stock
', 'def remove_zero_stock(stock):
    for item in list(stock.keys()):
        if stock[item] == 0:
            del stock[item]
    return stock
', 'function', 'remove_zero_stock', 'Unlike lists, Python actively detects a dictionary changing size while you iterate over it and raises an error rather than risk silently skipping or revisiting items. Looping over a separate list of the keys (taken before the loop starts) sidesteps the problem entirely.', 'Never add or remove keys from a dict while iterating directly over it - loop over `list(d.keys())` if you need to modify it as you go.', NULL, 'published', '04c77145e6f7f84cffd032f231c7fa1210cb37107ddf2a37d89d28b57a5f852c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 1, 'remove_zero_stock({"pens": 0, "pencils": 5})', '({''pens'': 0, ''pencils'': 5},)', NULL, NULL, 'returns', '{"pencils": 5}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 2, 'remove_zero_stock({"a": 1, "b": 2})', '({''a'': 1, ''b'': 2},)', NULL, NULL, 'returns', '{"a": 1, "b": 2}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 3, 'remove_zero_stock({"a": 0, "b": 0})', '({''a'': 0, ''b'': 0},)', NULL, NULL, 'returns', '{}', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 1, 'This crashes with a `RuntimeError` about the dictionary changing size.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 2, 'Python won''t let you add or remove keys from a dictionary while you''re directly looping over it. Can you loop over something else instead - a snapshot of the keys, perhaps?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 3, 'Loop over `list(stock.keys())` instead of `stock` directly.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'mutating-while-iterating'), 'Python detects that the dictionary''s size changed mid-loop (from `del`) and refuses to continue, since it can no longer guarantee which items have been visited.', 'Loop over a snapshot of the keys instead: `for item in list(stock.keys()):`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), (SELECT id FROM bh_concepts WHERE slug = 'mutating-while-iterating'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('sorted-wrong', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Sorted Wrong', 11, 3, NULL, 'logic', '`top_scorers(players)` takes a list of `(name, score)` tuples and should return the names of the 3 highest scorers, highest first.

Example: `top_scorers([("Al", 10), ("Bo", 30), ("Cy", 20), ("Di", 5)])` should return `["Bo", "Cy", "Al"]`.', 'def top_scorers(players):
    ranked = sorted(players, key=lambda p: p[1])
    return [name for name, score in ranked[:3]]
', 'def top_scorers(players):
    ranked = sorted(players, key=lambda p: p[1], reverse=True)
    return [name for name, score in ranked[:3]]
', 'function', 'top_scorers', '`sorted()` always sorts ascending (smallest first) unless told otherwise. Taking a slice from the front after sorting ascending gives you the smallest items, which is the opposite of "top" unless `reverse=True` is added.', 'After any `sorted()` call, check whether you want ascending or descending order, and whether `reverse=True` matches that.', NULL, 'published', 'c96c3ebe0c88c28ce451189a6fbfdffbba9aa1b40715d4cd28b068d39952fa2c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 1, 'top_scorers([("Al", 10), ("Bo", 30), ("Cy", 20), ("Di", 5)])', '([(''Al'', 10), (''Bo'', 30), (''Cy'', 20), (''Di'', 5)],)', NULL, NULL, 'returns', '["Bo", "Cy", "Al"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 2, 'top_scorers([("X", 1), ("Y", 2), ("Z", 3)])', '([(''X'', 1), (''Y'', 2), (''Z'', 3)],)', NULL, NULL, 'returns', '["Z", "Y", "X"]', 'exact', 0);
