INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 2, '`sorted()` arranges things smallest-to-largest by default. Does taking the first 3 of that give you the top, or the bottom?');
