INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'sorting'), '`sorted()` defaults to ascending order, so taking the first 3 items gives the lowest scorers, not the highest.', 'Add `reverse=True`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), (SELECT id FROM bh_concepts WHERE slug = 'sorting'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('silent-failure', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Silent Failure', 12, 4, NULL, 'logic', '`safe_divide(a, b)` should return `a` divided by `b`.

Example: `safe_divide(10, 2)` should return `5.0`.', 'def safe_divide(a, b):
    try:
        resutl = a / b
        return result
    except:
        return None
', 'def safe_divide(a, b):
    return a / b
', 'function', 'safe_divide', 'A bare `except:` catches every exception, including the ones you never intended to - like a plain typo. That turns a loud, obvious crash (which would have pointed straight at the mistake) into a silent wrong answer, which is much harder to track down.', 'Avoid bare `except:` - catch only the specific exception types you actually expect, so unexpected bugs stay loud instead of disappearing silently.', NULL, 'published', '3e202917d57036990d54c2b47c830e925075870015958591cb58b42f6c108c6b', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 1, 'safe_divide(10, 2)', '(10, 2)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 2, 'safe_divide(9, 3)', '(9, 3)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 3, 'safe_divide(7, 2)', '(7, 2)', NULL, NULL, 'returns', '3.5', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 1, 'This never crashes, but it also never seems to return the right answer - it just gives back `None` every time.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 2, 'A bare `except:` catches *every* kind of error, including ones caused by ordinary typos elsewhere in the same `try` block. Is there a typo hiding in there?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 3, 'There''s a spelling mistake (`resutl` vs `result`) causing a `NameError` that the bare `except` is silently swallowing. Fix the typo, and prefer not catching errors you don''t expect.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 1, 3, 6, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'exception-handling'), 'A typo (`resutl` instead of `result`) causes a `NameError` every single call, but the bare `except:` catches it silently and returns `None`, hiding the real bug completely.', 'Fix the typo, and avoid bare `except:` clauses that can hide genuine bugs like this one.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), (SELECT id FROM bh_concepts WHERE slug = 'exception-handling'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('equal-or-identical', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Equal or Identical', 13, 3, NULL, 'logic', '`same_contents(a, b)` should return `True` if two lists contain the same items in the same order, even if they are different list objects.

Example: `same_contents([1, 2, 3], [1, 2, 3])` should return `True`.', 'def same_contents(a, b):
    return a is b
', 'def same_contents(a, b):
    return a == b
', 'function', 'same_contents', '`==` asks "do these have the same value?"; `is` asks "are these the exact same object in memory?" Two separately built lists can hold identical values while being two completely different objects - which is the normal, expected case, not an edge case.', 'Use `==` to compare values (almost always what you want); reserve `is` for checking against `None` or confirming two names refer to the literal same object.', NULL, 'published', '9468ff7d79f67edee7cc7b2bd450032cbe01e9f8c5350295f115bf9cf18aae12', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 1, 'same_contents([1, 2, 3], [1, 2, 3])', '([1, 2, 3], [1, 2, 3])', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 2, 'same_contents([1, 2], [1, 2])', '([1, 2], [1, 2])', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 3, 'same_contents([1, 2], [2, 1])', '([1, 2], [2, 1])', NULL, NULL, 'returns', 'False', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 1, 'Two lists that clearly contain the same values still come back `False` - think about what''s actually being checked.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 2, '`is` checks whether two names point at the *exact same object* in memory, not whether their contents match.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 3, 'Use `==` instead of `is` to compare contents.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'identity-vs-equality'), '`is` checks object identity (are these literally the same object?), not equal contents - two separately-created lists with identical items are still different objects.', 'Use `==` to compare values instead of `is`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), (SELECT id FROM bh_concepts WHERE slug = 'identity-vs-equality'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('grade-calculator', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Grade Calculator', 1, 4, NULL, 'mixed', '`calculate_grade(scores)` takes a list of test scores (0-100) and returns a grade:

- `"Distinction"` if the average is 70 or above
- `"Pass"` if the average is 50 or above (but below 70)
- `"Fail"` otherwise
- `"No scores"` if the list is empty

Example: `calculate_grade([85, 90, 95])` should return `"Distinction"`.', 'def calculate_grade(scores):
    total = 0
    for score in scores:
        total = total + score
    average = total / len(scores)
    if average > 70:
        return "Distinction"
    elif average > 50:
        return "Pass"
    else:
        return "Fail"
', 'def calculate_grade(scores):
    if len(scores) == 0:
        return "No scores"
    total = 0
    for score in scores:
        total = total + score
    average = total / len(scores)
    if average >= 70:
        return "Distinction"
    elif average >= 50:
        return "Pass"
    else:
        return "Fail"
', 'function', 'calculate_grade', 'Two separate bugs here. First, dividing by `len(scores)` crashes on an empty list because there''s no guard for that case. Second, `>` silently excludes the boundary value itself - the brief says "70 or above", which means `>=`, not `>`. Neither bug stops the other from being tested, so fixing one doesn''t reveal the other automatically - you need to check both the empty case and the exact boundaries.', 'For any function with thresholds, test the exact boundary values by hand, and always ask what happens with an empty or missing input.', NULL, 'published', 'ceac46023d6e00ddb53fa86ed73cf3eaeae69912fbeaaa1e526640fc5f156c9b', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 1, 'calculate_grade([85, 90, 95])', '([85, 90, 95],)', NULL, NULL, 'returns', '"Distinction"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 2, 'calculate_grade([70, 70, 70]) - exactly on the Distinction boundary', '([70, 70, 70],)', NULL, NULL, 'returns', '"Distinction"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 3, 'calculate_grade([50, 50, 50]) - exactly on the Pass boundary', '([50, 50, 50],)', NULL, NULL, 'returns', '"Pass"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 4, 'calculate_grade([]) - no scores at all', '([],)', NULL, NULL, 'returns', '"No scores"', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 5, 'calculate_grade([30, 40])', '([30, 40],)', NULL, NULL, 'returns', '"Fail"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 1, 'Try scores that land exactly on 50 or 70, and try an empty list - does the brief''s boundary wording match what the code actually does?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 2, 'There are two separate problems here: what happens with no scores at all, and what happens exactly on a grade boundary.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 3, 'Guard against an empty list before dividing, and use `>=` instead of `>` so a score exactly on the boundary gets the higher grade.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 1, 5, 5, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'zero-division-and-guards'), 'If `scores` is empty, `len(scores)` is `0` and dividing by it crashes with a `ZeroDivisionError`.', 'Check for an empty list first and return `"No scores"` before dividing.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), 2, 6, 9, 'logic', NULL, 'Using `>` instead of `>=` means a score landing exactly on a boundary (70 or 50) is marked down a grade.', 'Change both comparisons to `>=` so the boundary itself counts for the higher grade.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grade-calculator'), (SELECT id FROM bh_concepts WHERE slug = 'zero-division-and-guards'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('caesar-cipher', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Caesar Cipher', 2, 4, NULL, 'mixed', '`encode(text, shift)` should shift every letter in `text` forward by `shift` places in the alphabet, wrapping around from Z back to A (and z back to a). Non-letter characters (spaces, punctuation) should be left unchanged, and case should be preserved.

Example: `encode("abc", 1)` should return `"bcd"`. `encode("xyz", 3)` should return `"abc"` (wrapping around).', 'def encode(text, shift):
    result = ""
    for ch in text:
        code = ord(ch) + shift
        result += chr(code)
    return result
', 'def encode(text, shift):
    result = ''''
    for ch in text:
        if ch.isupper():
            result += chr((ord(ch) - ord(''A'') + shift) % 26 + ord(''A''))
        elif ch.islower():
            result += chr((ord(ch) - ord(''a'') + shift) % 26 + ord(''a''))
        else:
            result += ch
    return result
', 'function', 'encode', 'Two bugs stack up here. Shifting by adding directly to the character code never wraps back around the alphabet - working in 0-25 alphabet positions with `% 26` fixes that. Separately, the code shifts *every* character, including spaces and punctuation, when only letters should move - those need an explicit check and a pass-through branch.', 'For cipher-style problems, test wraparound (shifting past ''z'') and non-letter characters (spaces, punctuation) as two separate boundary cases.', NULL, 'published', 'f30096f3a735a9e7be3bb8ac818429c8cddc3be37f6c7c39ebd177d055124450', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 1, 'encode("abc", 1)', '(''abc'', 1)', NULL, NULL, 'returns', '"bcd"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 2, 'encode("xyz", 3)', '(''xyz'', 3)', NULL, NULL, 'returns', '"abc"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 3, 'encode("Hello, World!", 5)', '(''Hello, World!'', 5)', NULL, NULL, 'returns', '"Mjqqt, Btwqi!"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 4, 'encode("ABC", 2)', '(''ABC'', 2)', NULL, NULL, 'returns', '"CDE"', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 5, 'encode("test", 0)', '(''test'', 0)', NULL, NULL, 'returns', '"test"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 1, 'Simple shifts work, but try shifting a letter near the end of the alphabet, and try text with spaces or punctuation in it.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 2, 'There are two separate problems: what happens when the shift goes past ''z'', and what happens to characters that aren''t letters at all.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 3, 'Use the alphabet position (`ord(ch) - ord(''a'')`), apply `% 26` to wrap around, then add `ord(''a'')` back - and leave non-letters untouched with an `else` branch.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), 'Adding `shift` directly to the character code doesn''t wrap around the alphabet - shifting ''z'' just gives the character after ''z'', not back to ''a''.', 'Work in alphabet positions 0-25 with `% 26` to wrap around, then convert back to a character.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'caesar-cipher'), 2, 4, 5, 'logic', NULL, 'Every character is shifted, including spaces and punctuation, which should be left exactly as they are.', 'Only shift letters (`ch.isupper()` or `ch.islower()`); copy everything else through unchanged.');

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('tic-tac-toe-winner', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Tic-Tac-Toe Winner', 3, 4, NULL, 'logic', '`winner(board)` takes a 3x3 list of lists, where each cell is `"X"`, `"O"`, or `""`. It should return `"X"` or `"O"` if that player has three in a row (row, column, or diagonal), `"Draw"` if the board is full with no winner, or `None` if the game is still in progress.

Example: a board with `"X"` down the main diagonal and nothing else should return `"X"`.', 'def winner(board):
    for row in board:
        if row[0] == row[1] == row[2] != '''':
            return row[0]
    for col in range(3):
        if board[0][col] == board[1][col] == board[2][col] != '''':
            return board[0][col]
    return None
', 'def winner(board):
    lines = []
    for row in board:
        lines.append(row)
    for col in range(3):
        lines.append([board[0][col], board[1][col], board[2][col]])
    lines.append([board[0][0], board[1][1], board[2][2]])
    lines.append([board[0][2], board[1][1], board[2][0]])
    for line in lines:
        if line[0] == line[1] == line[2] != '''':
            return line[0]
    if all(cell != '''' for row in board for cell in row):
        return ''Draw''
    return None
', 'function', 'winner', 'Tic-tac-toe has 8 possible winning lines - 3 rows, 3 columns, and 2 diagonals - and missing any category means some genuine wins go undetected. Separately, "no winner found" isn''t the same as "game over" - a full board with no three-in-a-row is a draw, which needs its own explicit check.', 'For a grid-based game, list every possible winning line on paper first, then check your code actually covers each one.', NULL, 'published', 'd2f4d3c0128491508f57568cc6cbae78abad574d9e0dc3b84d0aede13e611730', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 1, 'row win', '([[''X'', ''X'', ''X''], ['''', ''O'', ''''], [''O'', '''', '''']],)', NULL, NULL, 'returns', '"X"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 2, 'column win', '([[''O'', ''X'', ''''], [''O'', ''X'', ''''], [''O'', '''', ''X'']],)', NULL, NULL, 'returns', '"O"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 3, 'diagonal win', '([[''X'', ''O'', ''O''], [''O'', ''X'', ''''], [''O'', '''', ''X'']],)', NULL, NULL, 'returns', '"X"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 4, 'anti-diagonal win', '([[''O'', ''O'', ''X''], [''O'', ''X'', ''''], [''X'', '''', '''']],)', NULL, NULL, 'returns', '"X"', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 5, 'full board, no winner (draw)', '([[''X'', ''O'', ''X''], [''X'', ''O'', ''O''], [''O'', ''X'', ''X'']],)', NULL, NULL, 'returns', '"Draw"', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 6, 'game still in progress', '([[''X'', '''', ''''], ['''', '''', ''''], ['''', '''', '''']],)', NULL, NULL, 'returns', 'None', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 1, 'Row and column wins work, but try a board where only a diagonal has three in a row, and try a completely full board with no winner.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 2, 'How many different ways can three-in-a-row happen on this board? Rows and columns are checked - is that the complete list?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 3, 'Add checks for both diagonals, and after checking every line, check whether the board is completely full to detect a draw.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 1, 1, 8, 'logic', NULL, 'Only rows and columns are checked for a win - the two diagonals are never checked at all.', 'Also check `board[0][0], board[1][1], board[2][2]` and `board[0][2], board[1][1], board[2][0]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tic-tac-toe-winner'), 2, 8, 8, 'logic', NULL, 'A full board with no winner should return `"Draw"`, but this always returns `None` once every line has been checked.', 'After checking every line, check if every cell is filled and return `"Draw"` if so.');

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('bank-account', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Bank Account', 4, 5, NULL, 'mixed', 'An `Account` class should track its own balance and its own list of transactions independently from every other account, and should refuse to withdraw more than the current balance.

`run_bank_demo(initial_a, initial_b, withdraw_amount)` creates two accounts, withdraws `withdraw_amount` from the first, and returns `(account_a.balance, account_b.balance, len(account_b.transactions))`.', 'class Account:
    transactions = []

    def __init__(self, balance=0):
        self.balance = balance

    def withdraw(self, amount):
        self.balance -= amount
        self.transactions.append(amount)
        return self.balance


def run_bank_demo(initial_a, initial_b, withdraw_amount):
    a = Account(initial_a)
    b = Account(initial_b)
    a.withdraw(withdraw_amount)
    return [a.balance, b.balance, len(b.transactions)]
', 'class Account:
    def __init__(self, balance=0):
        self.balance = balance
        self.transactions = []

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("Insufficient funds")
        self.balance -= amount
        self.transactions.append(amount)
        return self.balance


def run_bank_demo(initial_a, initial_b, withdraw_amount):
    a = Account(initial_a)
    b = Account(initial_b)
    a.withdraw(withdraw_amount)
    return [a.balance, b.balance, len(b.transactions)]
', 'function', 'run_bank_demo', 'A mutable value defined directly under `class Account:` (rather than inside `__init__` with `self.`) is a class attribute, shared by every single instance - exactly the same trap as a mutable default argument, just in a different place. Separately, a withdrawal method that never checks the balance first will happily go negative, which real bank accounts should never allow.', 'Any mutable value (a list, dict, or another object) defined directly under a class line, not inside `__init__` with `self.`, is shared across every instance - give each instance its own copy in `__init__` instead.', NULL, 'published', 'c1760400678fdbc4ad310121c279866e89d47bb3b8edf051772eeb289770a6f9', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bank-account'), 1, 'withdrawing from one account should not affect another', '(100, 50, 30)', NULL, NULL, 'returns', '[70, 50, 0]', 'exact', 0);
