INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bank-account'), 3, 'Move `transactions = []` inside `__init__` as `self.transactions = []`, and add a balance check inside `withdraw` before subtracting.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bank-account'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'), '`transactions = []` written directly under the class is a *class* attribute, shared by every instance - one account''s withdrawals show up in every other account''s transaction list.', 'Move it inside `__init__` as `self.transactions = []` so each account gets its own list.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bank-account'), 2, 7, 9, 'logic', NULL, '`withdraw` never checks the balance, so an account can be withdrawn into a negative balance with no warning.', 'Raise an error (e.g. `ValueError`) if `amount` is more than `self.balance`.');
