INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('inventory-manager', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Inventory Manager', 5, 4, NULL, 'mixed', '`process_orders(stock, orders)` takes a stock dictionary (item name to quantity) and a list of `(item, quantity)` orders. It should reduce stock for each order, ignore orders for items not in stock, and return `(updated_stock, total_sold)`.

Example: `process_orders({"apples": 10, "pears": 5}, [("apples", 3)])` should return `({"apples": 7, "pears": 5}, 3)`.', 'def process_orders(stock, orders):
    total_sold = 0
    for item, qty in orders:
        stock[item] -= qty
        stock[item] -= qty
        total_sold += qty
    return [stock, total_sold]
', 'def process_orders(stock, orders):
    total_sold = 0
    for item, qty in orders:
        if item not in stock:
            continue
        stock[item] -= qty
        total_sold += qty
    return [stock, total_sold]
', 'function', 'process_orders', 'Two independent bugs here: a straightforwardly duplicated line that silently double-counts every sale, and a missing guard for orders that reference stock that doesn''t exist. Neither bug masks the other - fixing the duplicate still leaves the `KeyError` waiting for the next test that orders something unstocked.', 'Read every line as if it might be an accidental duplicate, especially inside a loop - and always test with an input that references something that doesn''t exist yet.', NULL, 'published', '8a3a193554648f15a4008b6aed48cd4cf2263ee66ae368747260161333269e44', NOW());
