INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('prime-sieve', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Prime Sieve', 6, 5, NULL, 'logic', '`primes_up_to(n)` should return a list of every prime number from 2 up to and including `n`.

Example: `primes_up_to(10)` should return `[2, 3, 5, 7]`.', 'def primes_up_to(n):
    is_prime = [True] * n
    is_prime[0] = False
    for i in range(2, n):
        if is_prime[i]:
            for multiple in range(i * 2, n, i):
                is_prime[multiple] = False
    return [i for i in range(n) if is_prime[i]]
', 'def primes_up_to(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, n + 1):
        if is_prime[i]:
            for multiple in range(i * i, n + 1, i):
                is_prime[multiple] = False
    return [i for i in range(n + 1) if is_prime[i]]
', 'function', 'primes_up_to', 'This classic algorithm has two boundary mistakes stacked together: the list size and loop bounds don''t reach the upper limit `n` itself (an inclusive-range off-by-one), and `1` - which is not prime by definition - is never explicitly excluded the way `0` is.', 'For range-based algorithms, always test the smallest and largest values your range is supposed to include, by hand.', NULL, 'published', '67edda7487e3fbd25e8f33a75b9e7a58c5c1486c5b828565836a6a3df6b65d30', NOW());
