INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'prime-sieve'), 1, 'Try `primes_up_to(2)` specifically - 2 is prime, so should it be included? Also check whether `1` ever shows up in a result list.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'prime-sieve'), 2, 'The list is sized `n`, and the loop runs `range(2, n)` - does either of those actually reach `n` itself? Also, is `1` ever explicitly marked as not prime?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'prime-sieve'), 3, 'Size the list `n + 1` and loop up to `n + 1` so `n` itself is included, and explicitly set `is_prime[1] = False` as well as `is_prime[0]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'prime-sieve'), 1, 2, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), 'The list has size `n` and the loops stop before reaching `n`, so `n` itself is never considered - even when it''s prime.', 'Size the list `n + 1` and loop through `range(2, n + 1)` so `n` is included.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'prime-sieve'), 2, 3, 3, 'logic', NULL, '`1` is never marked as not-prime (only index `0` is), so it can incorrectly show up in the result for small values of `n`.', 'Also set `is_prime[1] = False`.');
