INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('merge-sort', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Merge Sort', 7, 5, NULL, 'logic', '`merge_sort(items)` should return a new list containing every item from `items`, sorted in ascending order.

Example: `merge_sort([5, 2, 4, 1, 3])` should return `[1, 2, 3, 4, 5]`.', 'def merge_sort(items):
    if len(items) <= 1:
        return items
    mid = len(items) // 2
    left = merge_sort(items[:mid])
    right = merge_sort(items[mid:])
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    return merged
', 'def merge_sort(items):
    if len(items) <= 1:
        return items
    mid = len(items) // 2
    left = merge_sort(items[:mid])
    right = merge_sort(items[mid:])
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged
', 'function', 'merge_sort', 'The classic merge step compares the fronts of two already-sorted halves one at a time - but it only keeps comparing while *both* halves still have items left. The moment one half runs dry, the loop exits, and anything still waiting in the other half needs to be tacked on afterwards - a step that''s easy to forget since the function "looks finished" without it.', 'After any loop that processes two lists in lockstep, check: could one list still have leftover items when the loop ends? If so, they need handling separately.', NULL, 'published', '30e5277c11f847b0913126692287dcffd6ba67d285066427f3d4e4940c274173', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'merge-sort'), 1, 'merge_sort([5, 2, 4, 1, 3])', '([5, 2, 4, 1, 3],)', NULL, NULL, 'returns', '[1, 2, 3, 4, 5]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'merge-sort'), 2, 'merge_sort([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '[1, 2, 3]', 'exact', 0);
