INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-statistics'), 2, 'Does `"world!"` count as 6 characters long, or 5? And what does `len(words)` equal for an empty string, once split?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-statistics'), 3, 'Strip punctuation off each word before measuring its length, and return early with zeros when there are no words at all.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-statistics'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'zero-division-and-guards'), 'An empty (or whitespace-only) `text` produces an empty `words` list, and dividing by `len(words)` (which is `0`) crashes.', 'Check for an empty `words` list and return the zero-result early.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-statistics'), 2, 2, 2, 'logic', NULL, 'Punctuation attached to a word (like the comma in "Hello,") is counted as part of its length, inflating `avg_word_length`.', 'Strip punctuation characters off each word (e.g. with `.strip(''.,!?;:"\\'''')`) before measuring its length.');
