INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('shopping-cart', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Shopping Cart', 10, 4, NULL, 'logic', '`total_cost(prices, discount_percent)` should add up `prices`, then apply a percentage discount to the total, rounded to 2 decimal places.

Example: `total_cost([10, 20], 10)` should return `27.0` (30 total, minus 10%).', 'def total_cost(prices, discount_percent):
    total = sum(prices)
    discount = total - discount_percent / 100
    return round(total - discount, 2)
', 'def total_cost(prices, discount_percent):
    total = sum(prices)
    discount = total * (discount_percent / 100)
    return round(total - discount, 2)
', 'function', 'total_cost', 'A percentage discount needs to scale *with* the total - doubling the total should double the discount amount too. A formula built from subtraction instead of multiplication breaks that relationship entirely, and the wrongness is easy to miss unless you check a concrete example by hand.', 'For any calculation involving a percentage, sanity-check it on a round, easy number by hand (like 10% of 30) before trusting the formula.', NULL, 'published', 'c0b51f24513338eb363ddac9f3020286f7cd5d3025ea3719c164b357fa956fbc', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), 1, 'total_cost([10, 20], 10)', '([10, 20], 10)', NULL, NULL, 'returns', '27', 'float_tol', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), 2, 'total_cost([100], 50)', '([100], 50)', NULL, NULL, 'returns', '50', 'float_tol', 0);
