INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), 1, 'Try a simple case by hand: £30 total with a 10% discount should come to £27. Does it?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), 2, 'A percentage discount should be the total *multiplied by* the percentage, not the total *minus* the raw percentage number.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), 3, 'Change `discount = total - discount_percent / 100` to `discount = total * (discount_percent / 100)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), 1, 3, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'), 'The discount amount is computed as `total - discount_percent / 100`, which is nowhere close to "X% of the total" - it should be a multiplication, not a subtraction.', 'Compute the discount as `total * (discount_percent / 100)`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shopping-cart'), (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'));

